/** Vocabulario del dominio de liquidación (constantes inmutables). */
export const ClaimStatus = {
  REGISTRADO: 'REGISTRADO',
  LIQUIDADO: 'LIQUIDADO',
  RECHAZADO: 'RECHAZADO',
  PENDIENTE_REVISION: 'PENDIENTE_REVISION',
} as const;

export const PolicyStatus = { VIGENTE: 'VIGENTE' } as const;

export const Branch = { VIDA: 'VIDA' } as const;

export const CustomerCategory = { VIP: 'VIP' } as const;

export const DeductibleType = { FIJO: 'FIJO', PORCENTAJE: 'PORCENTAJE' } as const;

export const SettlementStatus = {
  APROBADA: 'APROBADA',
  RECHAZADA: 'RECHAZADA',
  PENDIENTE_APROBACION: 'PENDIENTE_APROBACION',
} as const;

export const ReasonCode = {
  POLIZA_NO_VIGENTE: 'POLIZA_NO_VIGENTE',
  FUERA_DE_VIGENCIA: 'FUERA_DE_VIGENCIA',
  DENUNCIA_EXTEMPORANEA: 'DENUNCIA_EXTEMPORANEA',
  COBERTURA_NO_CONTRATADA: 'COBERTURA_NO_CONTRATADA',
  EN_PERIODO_CARENCIA: 'EN_PERIODO_CARENCIA',
  PRIMA_EN_MORA: 'PRIMA_EN_MORA',
  BAJO_DEDUCIBLE: 'BAJO_DEDUCIBLE',
  SUMA_ASEGURADA_AGOTADA: 'SUMA_ASEGURADA_AGOTADA',
  SOSPECHA_FRAUDE: 'SOSPECHA_FRAUDE',
  SUPERA_TOPE_AUTOMATICO: 'SUPERA_TOPE_AUTOMATICO',
  LIQUIDACION_AUTOMATICA: 'LIQUIDACION_AUTOMATICA',
} as const;

export const ObservationMark = {
  TOLERANCIA_MORA_VIP: 'TOLERANCIA_MORA_VIP',
  LIMITE_COBERTURA: 'LIMITE_COBERTURA',
  DEDUCIBLE_MINIMO: 'DEDUCIBLE_MINIMO',
  DESCUENTO_VIP: 'DESCUENTO_VIP',
  PENALIZACION_SINIESTRALIDAD: 'PENALIZACION_SINIESTRALIDAD',
  TOPE_SUMA_ASEGURADA: 'TOPE_SUMA_ASEGURADA',
  RETENCION_APLICADA: 'RETENCION_APLICADA',
} as const;

export const ErrorCode = {
  INVALID_CLAIM_STATUS: 'ORA-20001',
  MISSING_PARAMETER: 'ORA-20010',
} as const;

export const ParameterName = {
  DIAS_MAX_DENUNCIA: 'DIAS_MAX_DENUNCIA',
  DIAS_MAX_DENUNCIA_VIDA: 'DIAS_MAX_DENUNCIA_VIDA',
  DEDUCIBLE_MINIMO: 'DEDUCIBLE_MINIMO',
  PCT_DESCUENTO_DED_VIP: 'PCT_DESCUENTO_DED_VIP',
  TOLERANCIA_MORA_VIP: 'TOLERANCIA_MORA_VIP',
  MAX_SINIESTROS_ANUAL: 'MAX_SINIESTROS_ANUAL',
  PCT_PENALIZACION_SINIEST: 'PCT_PENALIZACION_SINIEST',
  UMBRAL_RETENCION: 'UMBRAL_RETENCION',
  TASA_RETENCION: 'TASA_RETENCION',
  TOPE_AUTO_APROBACION: 'TOPE_AUTO_APROBACION',
  DIAS_ALERTA_FRAUDE: 'DIAS_ALERTA_FRAUDE',
  PCT_ALERTA_FRAUDE: 'PCT_ALERTA_FRAUDE',
} as const;

import { Decimal } from '../shared/decimal.ts';

/** Cero sin escala, para comparaciones. */
export const ZERO = Decimal.of('0');

/** Cero con escala 2, para importes. */
export const ZERO_AMOUNT = Decimal.of('0.00');

/** Constante 100 para porcentajes. */
export const HUNDRED = Decimal.of('100');

const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})/;

/**
 * Fecha de calendario sin hora (equivale a TRUNC(fecha) del legacy).
 * Internamente es un número entero de días desde 1970-01-01.
 */
export class CalendarDate {
  readonly epochDay: number;

  private constructor(epochDay: number) {
    this.epochDay = epochDay;
  }

  /** Interpreta 'YYYY-MM-DD' (ignora una hora posterior). Devuelve null si es inválida. */
  static parse(text: string): CalendarDate | null {
    const match = DATE_PATTERN.exec(text.trim());
    if (match === null) {
      return null;
    }
    const year = parseInt(match[1], 10);
    const month = parseInt(match[2], 10);
    const day = parseInt(match[3], 10);
    if (month < 1 || month > 12 || day < 1 || day > 31) {
      return null;
    }
    return new CalendarDate(CalendarDate.daysFromCivil(year, month, day));
  }

  private static daysFromCivil(year: number, month: number, day: number): number {
    const y = month <= 2 ? year - 1 : year;
    const era = Math.floor(y / 400);
    const yearOfEra = y - era * 400;
    const shiftedMonth = month > 2 ? month - 3 : month + 9;
    const dayOfYear = Math.floor((153 * shiftedMonth + 2) / 5) + day - 1;
    const dayOfEra =
      yearOfEra * 365 + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100) + dayOfYear;
    return era * 146097 + dayOfEra - 719468;
  }

  /** Días enteros desde esta fecha hasta `other` (other - this). */
  daysUntil(other: CalendarDate): number {
    return other.epochDay - this.epochDay;
  }

  isBefore(other: CalendarDate): boolean {
    return this.epochDay < other.epochDay;
  }

  isAfter(other: CalendarDate): boolean {
    return this.epochDay > other.epochDay;
  }
}

/** Lista inmutable de marcas de ajuste, serializada con ';'. */
export class Observations {
  private readonly marks: readonly string[];

  constructor(marks: readonly string[] = []) {
    this.marks = marks;
  }

  add(mark: string): Observations {
    return new Observations([...this.marks, mark]);
  }

  toString(): string {
    return this.marks.join(';');
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { ParameterName } from './Vocabulary.ts';
import { MissingParameterError } from '../exceptions/MissingParameterError.ts';

export const REQUIRED_PARAMETER_NAMES: readonly string[] = Object.values(ParameterName);

/**
 * Parámetros de negocio (LS_PARAMETROS).
 * @rule R-002
 */
export class BusinessParameters {
  private readonly values: ReadonlyMap<string, Decimal>;

  constructor(values: ReadonlyMap<string, Decimal>) {
    this.values = values;
  }

  /**
   * Nombres de parámetros requeridos que no están definidos.
   * @rule R-002
   */
  missingNames(): readonly string[] {
    return REQUIRED_PARAMETER_NAMES.filter((name) => !this.values.has(name));
  }

  /**
   * Valor de un parámetro; falla si no existe (se valida antes con missingNames).
   * @rule R-002
   */
  get(name: string): Decimal {
    const value = this.values.get(name);
    if (value === undefined) {
      throw new MissingParameterError(name);
    }
    return value;
  }
}

/**
 * Violación de invariante interna: se pidió un parámetro no validado.
 * Los errores de negocio se devuelven como Settlement, no como excepciones.
 * @rule R-002
 */
export class MissingParameterError extends Error {
  readonly parameterName: string;

  constructor(parameterName: string) {
    super('Parámetro no definido: ' + parameterName);
    this.parameterName = parameterName;
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { CalendarDate } from './CalendarDate.ts';

/** Datos de entrada del siniestro, póliza, cliente y cobertura. */
export interface ClaimCase {
  readonly claimStatus: string;
  readonly claimedAmount: Decimal;
  readonly occurrenceDate: CalendarDate;
  readonly reportDate: CalendarDate;
  readonly processDate: CalendarDate;
  readonly policyStatus: string;
  readonly policyBranch: string;
  readonly policyStartDate: CalendarDate;
  readonly policyEndDate: CalendarDate;
  readonly sumInsured: Decimal;
  readonly deductibleType: string;
  readonly deductibleValue: Decimal;
  readonly pendingPremium: Decimal;
  readonly customerCategory: string;
  readonly coverageFound: boolean;
  readonly coverageLimit: Decimal;
  readonly coveragePercentage: Decimal;
  readonly waitingDays: number;
  readonly priorLiquidatedClaims365d: number;
  readonly totalIndemnified: Decimal;
}

import type { Decimal } from '../shared/decimal.ts';
import type { ClaimCase } from './ClaimCase.ts';
import type { BusinessParameters } from './BusinessParameters.ts';
import { Observations } from './Observations.ts';
import { ZERO_AMOUNT } from './Zero.ts';

/** Estado inmutable que fluye por el pipeline de reglas. */
export interface LiquidationState {
  readonly claim: ClaimCase;
  readonly params: BusinessParameters;
  readonly observations: Observations;
  readonly baseAmount: Decimal;
  readonly deductibleAmount: Decimal;
  readonly coveredAmount: Decimal;
  readonly withholdingAmount: Decimal;
  readonly netAmount: Decimal;
}

export function initialState(claim: ClaimCase, params: BusinessParameters): LiquidationState {
  return {
    claim,
    params,
    observations: new Observations(),
    baseAmount: ZERO_AMOUNT,
    deductibleAmount: ZERO_AMOUNT,
    coveredAmount: ZERO_AMOUNT,
    withholdingAmount: ZERO_AMOUNT,
    netAmount: ZERO_AMOUNT,
  };
}

export function evolve(state: LiquidationState, patch: Partial<LiquidationState>): LiquidationState {
  return { ...state, ...patch };
}

import type { Decimal } from '../shared/decimal.ts';
import type { Observations } from './Observations.ts';
import { SettlementStatus, ClaimStatus } from './Vocabulary.ts';
import { ZERO_AMOUNT } from './Zero.ts';

export interface SettlementProps {
  readonly status: string;
  readonly reasonCode: string;
  readonly baseAmount: Decimal;
  readonly deductibleAmount: Decimal;
  readonly coveredAmount: Decimal;
  readonly withholdingAmount: Decimal;
  readonly netAmount: Decimal;
  readonly observations: string;
  readonly claimNewStatus: string;
  readonly errorCode: string | null;
}

/** Resultado de la liquidación de un siniestro. */
export class Settlement {
  readonly status: string;
  readonly reasonCode: string;
  readonly baseAmount: Decimal;
  readonly deductibleAmount: Decimal;
  readonly coveredAmount: Decimal;
  readonly withholdingAmount: Decimal;
  readonly netAmount: Decimal;
  readonly observations: string;
  readonly claimNewStatus: string;
  readonly errorCode: string | null;

  constructor(props: SettlementProps) {
    this.status = props.status;
    this.reasonCode = props.reasonCode;
    this.baseAmount = props.baseAmount;
    this.deductibleAmount = props.deductibleAmount;
    this.coveredAmount = props.coveredAmount;
    this.withholdingAmount = props.withholdingAmount;
    this.netAmount = props.netAmount;
    this.observations = props.observations;
    this.claimNewStatus = props.claimNewStatus;
    this.errorCode = props.errorCode;
  }

  /**
   * Rechazo: importes en 0, estado RECHAZADA y siniestro RECHAZADO.
   * @rule R-017
   * @rule R-003
   */
  static rejected(reasonCode: string, observations: Observations): Settlement {
    return new Settlement({
      status: SettlementStatus.RECHAZADA,
      reasonCode,
      baseAmount: ZERO_AMOUNT,
      deductibleAmount: ZERO_AMOUNT,
      coveredAmount: ZERO_AMOUNT,
      withholdingAmount: ZERO_AMOUNT,
      netAmount: ZERO_AMOUNT,
      observations: observations.toString(),
      claimNewStatus: ClaimStatus.RECHAZADO,
      errorCode: null,
    });
  }

  /**
   * Error de proceso (p. ej. ORA-20001, ORA-20010): sin liquidación, valores por defecto.
   * @rule R-001
   * @rule R-002
   */
  static failed(errorCode: string): Settlement {
    return new Settlement({
      status: '',
      reasonCode: '',
      baseAmount: ZERO_AMOUNT,
      deductibleAmount: ZERO_AMOUNT,
      coveredAmount: ZERO_AMOUNT,
      withholdingAmount: ZERO_AMOUNT,
      netAmount: ZERO_AMOUNT,
      observations: '',
      claimNewStatus: '',
      errorCode,
    });
  }
}

import { Decimal } from '../shared/decimal.ts';
import { HUNDRED } from '../model/Zero.ts';

/**
 * ROUND(amount * pct / 100, 2) con redondeo HALF_UP.
 * @rule R-010
 * @rule R-012
 * @rule R-015
 * @rule R-016
 */
export function percentageOf(amount: Decimal, pct: Decimal): Decimal {
  return amount.times(pct).dividedBy(HUNDRED, 2, 'HALF_UP');
}

/**
 * ROUND(amount * (100 - pct) / 100, 2) con redondeo HALF_UP.
 * @rule R-011
 * @rule R-013
 */
export function afterDiscount(amount: Decimal, pct: Decimal): Decimal {
  return amount.times(HUNDRED.minus(pct)).dividedBy(HUNDRED, 2, 'HALF_UP');
}

/** Convierte un conteo entero de días a Decimal para compararlo con parámetros. */
export function daysAsDecimal(days: number): Decimal {
  return Decimal.of(days);
}

import type { LiquidationState } from '../model/LiquidationState.ts';
import type { Observations } from '../model/Observations.ts';

export interface ContinueResult {
  readonly kind: 'continue';
  readonly state: LiquidationState;
}

export interface RejectResult {
  readonly kind: 'reject';
  readonly reasonCode: string;
  readonly observations: Observations;
}

export type StepResult = ContinueResult | RejectResult;

/** Paso del pipeline: implementa una regla de negocio. */
export interface LiquidationStep {
  apply(state: LiquidationState): StepResult;
}

export function proceed(state: LiquidationState): StepResult {
  return { kind: 'continue', state };
}

/** Rechaza conservando las observaciones acumuladas. */
export function rejectWith(state: LiquidationState, reasonCode: string): StepResult {
  return { kind: 'reject', reasonCode, observations: state.observations };
}

import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { Settlement } from '../model/Settlement.ts';
import { ClaimStatus, ErrorCode } from '../model/Vocabulary.ts';

/** Precondiciones del proceso: abortan sin generar liquidación. */
export class LiquidationPreconditions {
  /**
   * Valida estado REGISTRADO y parámetros completos. Devuelve el error o null si todo está bien.
   * @rule R-001
   * @rule R-002
   */
  check(claimStatus: string, params: BusinessParameters): Settlement | null {
    if (claimStatus !== ClaimStatus.REGISTRADO) {
      return Settlement.failed(ErrorCode.INVALID_CLAIM_STATUS);
    }
    if (params.missingNames().length > 0) {
      return Settlement.failed(ErrorCode.MISSING_PARAMETER);
    }
    return null;
  }
}

import type { LiquidationState } from '../model/LiquidationState.ts';
import { evolve } from '../model/LiquidationState.ts';
import type { ClaimCase } from '../model/ClaimCase.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { Branch, CustomerCategory, ObservationMark, ParameterName, PolicyStatus, ReasonCode } from '../model/Vocabulary.ts';
import { ZERO } from '../model/Zero.ts';
import type { LiquidationStep, StepResult } from './LiquidationStep.ts';
import { proceed, rejectWith } from './LiquidationStep.ts';
import { daysAsDecimal } from './Percentages.ts';

/** @rule R-003 Solo se liquidan pólizas VIGENTES. */
export class PolicyInForceStep implements LiquidationStep {
  /** @rule R-003 */
  apply(state: LiquidationState): StepResult {
    if (state.claim.policyStatus !== PolicyStatus.VIGENTE) {
      return rejectWith(state, ReasonCode.POLIZA_NO_VIGENTE);
    }
    return proceed(state);
  }
}

/** @rule R-004 Ocurrencia dentro de la vigencia, extremos inclusive. */
export class OccurrenceWithinPolicyPeriodStep implements LiquidationStep {
  /** @rule R-004 */
  apply(state: LiquidationState): StepResult {
    const { occurrenceDate, policyStartDate, policyEndDate } = state.claim;
    if (occurrenceDate.isBefore(policyStartDate) || occurrenceDate.isAfter(policyEndDate)) {
      return rejectWith(state, ReasonCode.FUERA_DE_VIGENCIA);
    }
    return proceed(state);
  }
}

/** @rule R-005 Plazo máximo de denuncia (día límite inclusive). */
export class ReportDeadlineStep implements LiquidationStep {
  /** @rule R-005 */
  apply(state: LiquidationState): StepResult {
    const days = state.claim.occurrenceDate.daysUntil(state.claim.reportDate);
    const maxDays = this.maxDaysFor(state.claim, state.params);
    if (daysAsDecimal(days).gt(maxDays)) {
      return rejectWith(state, ReasonCode.DENUNCIA_EXTEMPORANEA);
    }
    return proceed(state);
  }

  /** @rule R-005 */
  private maxDaysFor(claim: ClaimCase, params: BusinessParameters) {
    const name =
      claim.policyBranch === Branch.VIDA
        ? ParameterName.DIAS_MAX_DENUNCIA_VIDA
        : ParameterName.DIAS_MAX_DENUNCIA;
    return params.get(name);
  }
}

/** @rule R-006 La cobertura reclamada debe estar contratada. */
export class CoverageContractedStep implements LiquidationStep {
  /** @rule R-006 */
  apply(state: LiquidationState): StepResult {
    if (!state.claim.coverageFound) {
      return rejectWith(state, ReasonCode.COBERTURA_NO_CONTRATADA);
    }
    return proceed(state);
  }
}

/** @rule R-007 Periodo de carencia (el día exacto cuenta como activo). */
export class WaitingPeriodStep implements LiquidationStep {
  /** @rule R-007 */
  apply(state: LiquidationState): StepResult {
    const daysSinceStart = state.claim.policyStartDate.daysUntil(state.claim.occurrenceDate);
    if (daysSinceStart < state.claim.waitingDays) {
      return rejectWith(state, ReasonCode.EN_PERIODO_CARENCIA);
    }
    return proceed(state);
  }
}

/** @rule R-008 Morosidad de prima con tolerancia VIP. */
export class PremiumArrearsStep implements LiquidationStep {
  /** @rule R-008 */
  apply(state: LiquidationState): StepResult {
    if (!state.claim.pendingPremium.gt(ZERO)) {
      return proceed(state);
    }
    if (this.isVipWithinTolerance(state)) {
      const marked = state.observations.add(ObservationMark.TOLERANCIA_MORA_VIP);
      return proceed(evolve(state, { observations: marked }));
    }
    return rejectWith(state, ReasonCode.PRIMA_EN_MORA);
  }

  /** @rule R-008 */
  private isVipWithinTolerance(state: LiquidationState): boolean {
    const tolerance = state.params.get(ParameterName.TOLERANCIA_MORA_VIP);
    return (
      state.claim.customerCategory === CustomerCategory.VIP &&
      state.claim.pendingPremium.lte(tolerance)
    );
  }
}

import type { LiquidationState } from '../model/LiquidationState.ts';
import { evolve } from '../model/LiquidationState.ts';
import { Branch, CustomerCategory, DeductibleType, ObservationMark, ParameterName, ReasonCode } from '../model/Vocabulary.ts';
import { ZERO, ZERO_AMOUNT } from '../model/Zero.ts';
import type { LiquidationStep, StepResult } from './LiquidationStep.ts';
import { proceed, rejectWith } from './LiquidationStep.ts';
import { afterDiscount, daysAsDecimal, percentageOf } from './Percentages.ts';

/** @rule R-009 Monto base topado por el límite de cobertura. */
export class BaseAmountStep implements LiquidationStep {
  /** @rule R-009 */
  apply(state: LiquidationState): StepResult {
    const { claimedAmount, coverageLimit } = state.claim;
    if (claimedAmount.gt(coverageLimit)) {
      const marked = state.observations.add(ObservationMark.LIMITE_COBERTURA);
      return proceed(evolve(state, { baseAmount: coverageLimit, observations: marked }));
    }
    return proceed(evolve(state, { baseAmount: claimedAmount }));
  }
}

/** @rule R-010 Cálculo del deducible sobre el monto base. */
export class DeductibleStep implements LiquidationStep {
  /** @rule R-010 */
  apply(state: LiquidationState): StepResult {
    const { deductibleType, deductibleValue } = state.claim;
    if (deductibleType === DeductibleType.FIJO) {
      return proceed(evolve(state, { deductibleAmount: deductibleValue }));
    }
    return proceed(this.applyPercentage(state));
  }

  /** @rule R-010 */
  private applyPercentage(state: LiquidationState): LiquidationState {
    const computed = percentageOf(state.baseAmount, state.claim.deductibleValue);
    const minimum = state.params.get(ParameterName.DEDUCIBLE_MINIMO);
    if (computed.lt(minimum)) {
      const marked = state.observations.add(ObservationMark.DEDUCIBLE_MINIMO);
      return evolve(state, { deductibleAmount: minimum.setScale(2, 'HALF_UP'), observations: marked });
    }
    return evolve(state, { deductibleAmount: computed });
  }
}

/** @rule R-011 Descuento VIP sobre el deducible (posterior al mínimo). */
export class VipDeductibleDiscountStep implements LiquidationStep {
  /** @rule R-011 */
  apply(state: LiquidationState): StepResult {
    const isVip = state.claim.customerCategory === CustomerCategory.VIP;
    if (!isVip || !state.deductibleAmount.gt(ZERO)) {
      return proceed(state);
    }
    const pct = state.params.get(ParameterName.PCT_DESCUENTO_DED_VIP);
    const marked = state.observations.add(ObservationMark.DESCUENTO_VIP);
    return proceed(
      evolve(state, { deductibleAmount: afterDiscount(state.deductibleAmount, pct), observations: marked }),
    );
  }
}

/** @rule R-012 Monto cubierto y rechazo BAJO_DEDUCIBLE. */
export class CoveredAmountStep implements LiquidationStep {
  /** @rule R-012 */
  apply(state: LiquidationState): StepResult {
    const afterDeductible = state.baseAmount.minus(state.deductibleAmount);
    const covered = percentageOf(afterDeductible, state.claim.coveragePercentage);
    if (covered.lte(ZERO)) {
      return rejectWith(state, ReasonCode.BAJO_DEDUCIBLE);
    }
    return proceed(evolve(state, { coveredAmount: covered }));
  }
}

/** @rule R-013 Penalización por siniestralidad en los últimos 365 días. */
export class ClaimsFrequencyPenaltyStep implements LiquidationStep {
  /** @rule R-013 */
  apply(state: LiquidationState): StepResult {
    const maxClaims = state.params.get(ParameterName.MAX_SINIESTROS_ANUAL);
    if (!daysAsDecimal(state.claim.priorLiquidatedClaims365d).gte(maxClaims)) {
      return proceed(state);
    }
    const pct = state.params.get(ParameterName.PCT_PENALIZACION_SINIEST);
    const marked = state.observations.add(ObservationMark.PENALIZACION_SINIESTRALIDAD);
    return proceed(
      evolve(state, { coveredAmount: afterDiscount(state.coveredAmount, pct), observations: marked }),
    );
  }
}

/** @rule R-014 Tope por suma asegurada remanente. */
export class InsuredSumCapStep implements LiquidationStep {
  /** @rule R-014 */
  apply(state: LiquidationState): StepResult {
    const remaining = state.claim.sumInsured.minus(state.claim.totalIndemnified);
    if (remaining.lte(ZERO)) {
      return rejectWith(state, ReasonCode.SUMA_ASEGURADA_AGOTADA);
    }
    if (state.coveredAmount.gt(remaining)) {
      const marked = state.observations.add(ObservationMark.TOPE_SUMA_ASEGURADA);
      return proceed(evolve(state, { coveredAmount: remaining, observations: marked }));
    }
    return proceed(state);
  }
}

/** @rule R-015 Retención impositiva y neto. */
export class WithholdingStep implements LiquidationStep {
  /** @rule R-015 */
  apply(state: LiquidationState): StepResult {
    const threshold = state.params.get(ParameterName.UMBRAL_RETENCION);
    const applies = state.claim.policyBranch !== Branch.VIDA && state.coveredAmount.gt(threshold);
    if (!applies) {
      return proceed(evolve(state, { withholdingAmount: ZERO_AMOUNT, netAmount: state.coveredAmount }));
    }
    const rate = state.params.get(ParameterName.TASA_RETENCION);
    const withholding = percentageOf(state.coveredAmount, rate);
    const marked = state.observations.add(ObservationMark.RETENCION_APLICADA);
    return proceed(
      evolve(state, {
        withholdingAmount: withholding,
        netAmount: state.coveredAmount.minus(withholding),
        observations: marked,
      }),
    );
  }
}

import type { LiquidationState } from '../model/LiquidationState.ts';
import { Settlement } from '../model/Settlement.ts';
import { ClaimStatus, ParameterName, ReasonCode, SettlementStatus } from '../model/Vocabulary.ts';
import { daysAsDecimal, percentageOf } from './Percentages.ts';

interface Outcome {
  readonly status: string;
  readonly reasonCode: string;
  readonly claimNewStatus: string;
}

const FRAUD_SUSPECTED: Outcome = {
  status: SettlementStatus.PENDIENTE_APROBACION,
  reasonCode: ReasonCode.SOSPECHA_FRAUDE,
  claimNewStatus: ClaimStatus.PENDIENTE_REVISION,
};

const ABOVE_AUTOMATIC_CAP: Outcome = {
  status: SettlementStatus.PENDIENTE_APROBACION,
  reasonCode: ReasonCode.SUPERA_TOPE_AUTOMATICO,
  claimNewStatus: ClaimStatus.PENDIENTE_REVISION,
};

const AUTOMATIC_APPROVAL: Outcome = {
  status: SettlementStatus.APROBADA,
  reasonCode: ReasonCode.LIQUIDACION_AUTOMATICA,
  claimNewStatus: ClaimStatus.LIQUIDADO,
};

/** Determina el estado final de una liquidación calculada. */
export class FinalDecisionPolicy {
  /**
   * Fraude (prioridad), tope automático o aprobación automática.
   * @rule R-016
   */
  decide(state: LiquidationState): Settlement {
    const outcome = this.selectOutcome(state);
    return new Settlement({
      status: outcome.status,
      reasonCode: outcome.reasonCode,
      baseAmount: state.baseAmount,
      deductibleAmount: state.deductibleAmount,
      coveredAmount: state.coveredAmount,
      withholdingAmount: state.withholdingAmount,
      netAmount: state.netAmount,
      observations: state.observations.toString(),
      claimNewStatus: outcome.claimNewStatus,
      errorCode: null,
    });
  }

  /** @rule R-016 */
  private selectOutcome(state: LiquidationState): Outcome {
    if (this.isFraudSuspected(state)) {
      return FRAUD_SUSPECTED;
    }
    const cap = state.params.get(ParameterName.TOPE_AUTO_APROBACION);
    return state.netAmount.gt(cap) ? ABOVE_AUTOMATIC_CAP : AUTOMATIC_APPROVAL;
  }

  /** @rule R-016 */
  private isFraudSuspected(state: LiquidationState): boolean {
    const { claim, params } = state;
    const daysSinceStart = claim.policyStartDate.daysUntil(claim.occurrenceDate);
    const alertDays = params.get(ParameterName.DIAS_ALERTA_FRAUDE);
    const threshold = percentageOf(claim.coverageLimit, params.get(ParameterName.PCT_ALERTA_FRAUDE));
    return daysAsDecimal(daysSinceStart).lte(alertDays) && claim.claimedAmount.gte(threshold);
  }
}

import type { ClaimCase } from '../model/ClaimCase.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { initialState } from '../model/LiquidationState.ts';
import type { Settlement as SettlementType } from '../model/Settlement.ts';
import { Settlement } from '../model/Settlement.ts';
import type { LiquidationStep } from './LiquidationStep.ts';
import { FinalDecisionPolicy } from './FinalDecisionPolicy.ts';
import {
  CoverageContractedStep,
  OccurrenceWithinPolicyPeriodStep,
  PolicyInForceStep,
  PremiumArrearsStep,
  ReportDeadlineStep,
  WaitingPeriodStep,
} from './EligibilitySteps.ts';
import {
  BaseAmountStep,
  ClaimsFrequencyPenaltyStep,
  CoveredAmountStep,
  DeductibleStep,
  InsuredSumCapStep,
  VipDeductibleDiscountStep,
  WithholdingStep,
} from './CalculationSteps.ts';

/** Orquesta el pipeline de reglas de liquidación. */
export class ClaimLiquidationService {
  private readonly steps: readonly LiquidationStep[];
  private readonly finalDecision: FinalDecisionPolicy;

  constructor(steps: readonly LiquidationStep[], finalDecision: FinalDecisionPolicy) {
    this.steps = steps;
    this.finalDecision = finalDecision;
  }

  /** Pipeline estándar R-003..R-015 más decisión final R-016. */
  static standard(): ClaimLiquidationService {
    return new ClaimLiquidationService(
      [
        new PolicyInForceStep(),
        new OccurrenceWithinPolicyPeriodStep(),
        new ReportDeadlineStep(),
        new CoverageContractedStep(),
        new WaitingPeriodStep(),
        new PremiumArrearsStep(),
        new BaseAmountStep(),
        new DeductibleStep(),
        new VipDeductibleDiscountStep(),
        new CoveredAmountStep(),
        new ClaimsFrequencyPenaltyStep(),
        new InsuredSumCapStep(),
        new WithholdingStep(),
      ],
      new FinalDecisionPolicy(),
    );
  }

  /**
   * Ejecuta los pasos en orden; ante un rechazo devuelve importes en cero.
   * @rule R-017
   * @rule R-016
   */
  liquidate(claim: ClaimCase, params: BusinessParameters): SettlementType {
    let state = initialState(claim, params);
    for (const step of this.steps) {
      const result = step.apply(state);
      if (result.kind === 'reject') {
        return Settlement.rejected(result.reasonCode, result.observations);
      }
      state = result.state;
    }
    return this.finalDecision.decide(state);
  }
}

import type { CalendarDate } from '../model/CalendarDate.ts';
import { ClaimStatus } from '../model/Vocabulary.ts';

export interface BatchCandidate {
  readonly claimId: string;
  readonly claimStatus: string;
  readonly reportDate: CalendarDate;
}

/** Política de selección de siniestros del lote. */
export class BatchSelectionPolicy {
  /**
   * REGISTRADO con fecha de denuncia <= fecha de proceso.
   * @rule R-018
   */
  isSelectable(candidate: BatchCandidate, processDate: CalendarDate): boolean {
    return candidate.claimStatus === ClaimStatus.REGISTRADO && !candidate.reportDate.isAfter(processDate);
  }

  /**
   * Siniestros elegibles en orden ascendente de ID (numérico). Cada uno se liquida de forma independiente.
   * @rule R-018
   */
  select(candidates: readonly BatchCandidate[], processDate: CalendarDate): readonly BatchCandidate[] {
    return candidates
      .filter((candidate) => this.isSelectable(candidate, processDate))
      .sort((a, b) => BatchSelectionPolicy.compareIds(a.claimId, b.claimId));
  }

  /** @rule R-018 */
  private static compareIds(a: string, b: string): number {
    if (a.length !== b.length) {
      return a.length - b.length;
    }
    if (a === b) {
      return 0;
    }
    return a < b ? -1 : 1;
  }
}

