/** Caso de uso: liquidar un siniestro. */
export class LiquidateClaimUseCase {
  private readonly preconditions: LiquidationPreconditions;
  private readonly liquidation: ClaimLiquidationService;
  private readonly audit: AuditLogPort;

  constructor(
    preconditions: LiquidationPreconditions,
    liquidation: ClaimLiquidationService,
    audit: AuditLogPort,
  ) {
    this.preconditions = preconditions;
    this.liquidation = liquidation;
    this.audit = audit;
  }

  execute(command: LiquidateClaimCommand): Settlement {
    const failure = this.preconditions.check(command.claim.claimStatus, command.params);
    const settlement = failure ?? this.liquidation.liquidate(command.claim, command.params);
    this.audit.record({
      status: settlement.status,
      reasonCode: settlement.reasonCode,
      errorCode: settlement.errorCode,
    });
    return settlement;
  }
}

