import { Decimal } from '../domain/shared/decimal.ts';
import { CalendarDate } from '../domain/model/CalendarDate.ts';

const DECIMAL_PATTERN = /^-?\d+(\.\d+)?$/;
const INTEGER_PATTERN = /^\d+$/;

/** Error de formato en un campo de entrada (solo infraestructura). */
export class InputFieldError extends Error {
  readonly field: string;

  constructor(field: string) {
    super('Campo inválido: ' + field);
    this.field = field;
  }
}

/** Lee y convierte los valores string de la entrada a tipos del dominio. */
export class InputReader {
  private readonly input: Record<string, string>;

  constructor(input: Record<string, string>) {
    this.input = input;
  }

  private raw(field: string): string {
    const value = this.input[field];
    if (typeof value !== 'string' || value.trim() === '') {
      throw new InputFieldError(field);
    }
    return value.trim();
  }

  text(field: string): string {
    return this.raw(field);
  }

  optionalText(field: string): string {
    const value = this.input[field];
    return typeof value === 'string' ? value : '';
  }

  decimal(field: string): Decimal {
    const value = this.raw(field);
    if (!DECIMAL_PATTERN.test(value)) {
      throw new InputFieldError(field);
    }
    return Decimal.of(value);
  }

  integer(field: string): number {
    const value = this.raw(field);
    if (!INTEGER_PATTERN.test(value)) {
      throw new InputFieldError(field);
    }
    return parseInt(value, 10);
  }

  date(field: string): CalendarDate {
    const parsed = CalendarDate.parse(this.raw(field));
    if (parsed === null) {
      throw new InputFieldError(field);
    }
    return parsed;
  }

  boolean(field: string): boolean {
    const value = this.raw(field).toLowerCase();
    if (value === 'true' || value === '1' || value === 's') {
      return true;
    }
    if (value === 'false' || value === '0' || value === 'n') {
      return false;
    }
    throw new InputFieldError(field);
  }
}

import { Decimal } from '../domain/shared/decimal.ts';
import { BusinessParameters } from '../domain/model/BusinessParameters.ts';
import type { ClaimCase } from '../domain/model/ClaimCase.ts';
import type { LiquidateClaimCommand } from '../application/LiquidateClaimCommand.ts';
import { InputFieldError, InputReader } from './InputReader.ts';

const PARAM_VALUE_PATTERN = /^-?\d+(\.\d+)?$/;

export type MappingResult =
  | { readonly ok: true; readonly command: LiquidateClaimCommand }
  | { readonly ok: false; readonly field: string };

/** Adaptador de entrada: convierte el mapa de strings en un comando del dominio. */
export class ClaimInputMapper {
  map(input: Record<string, string>): MappingResult {
    try {
      const reader = new InputReader(input);
      const params = ClaimInputMapper.parseParameters(reader.optionalText('params'));
      return { ok: true, command: { claim: ClaimInputMapper.readClaim(reader), params } };
    } catch (error) {
      if (error instanceof InputFieldError) {
        return { ok: false, field: error.field };
      }
      throw error;
    }
  }

  private static readClaim(reader: InputReader): ClaimCase {
    return {
      claimStatus: reader.text('claim_status'),
      claimedAmount: reader.decimal('claimed_amount'),
      occurrenceDate: reader.date('occurrence_date'),
      reportDate: reader.date('report_date'),
      processDate: reader.date('process_date'),
      policyStatus: reader.text('policy_status'),
      policyBranch: reader.text('policy_branch'),
      policyStartDate: reader.date('policy_start_date'),
      policyEndDate: reader.date('policy_end_date'),
      sumInsured: reader.decimal('sum_insured'),
      deductibleType: reader.text('deductible_type'),
      deductibleValue: reader.decimal('deductible_value'),
      pendingPremium: reader.decimal('pending_premium'),
      customerCategory: reader.text('customer_category'),
      coverageFound: reader.boolean('coverage_found'),
      coverageLimit: reader.decimal('coverage_limit'),
      coveragePercentage: reader.decimal('coverage_percentage'),
      waitingDays: reader.integer('waiting_days'),
      priorLiquidatedClaims365d: reader.integer('prior_liquidated_claims_365d'),
      totalIndemnified: reader.decimal('total_indemnified'),
    };
  }

  /** Interpreta 'NOMBRE=valor;NOMBRE=valor'. Las entradas inválidas se ignoran (quedan como faltantes). */
  private static parseParameters(raw: string): BusinessParameters {
    const values = new Map<string, Decimal>();
    for (const segment of raw.split(/[;\n]/)) {
      const separator = segment.indexOf('=');
      if (separator < 0) {
        continue;
      }
      const name = segment.slice(0, separator).trim().toUpperCase();
      const text = segment.slice(separator + 1).trim();
      if (PARAM_VALUE_PATTERN.test(text)) {
        values.set(name, Decimal.of(text));
      }
    }
    return new BusinessParameters(values);
  }
}

import type { Decimal } from '../domain/shared/decimal.ts';
import type { Settlement } from '../domain/model/Settlement.ts';

/** Adaptador de salida: serializa el resultado a cadenas con escala exacta. */
export class SettlementOutputMapper {
  toRecord(settlement: Settlement): Record<string, string> {
    return {
      status: settlement.status,
      reason_code: settlement.reasonCode,
      base_amount: this.amount(settlement.baseAmount),
      deductible_amount: this.amount(settlement.deductibleAmount),
      covered_amount: this.amount(settlement.coveredAmount),
      withholding_amount: this.amount(settlement.withholdingAmount),
      net_amount: this.amount(settlement.netAmount),
      observations: settlement.observations,
      claim_new_status: settlement.claimNewStatus,
      error_code: settlement.errorCode ?? '',
    };
  }

  private amount(value: Decimal): string {
    return value.setScale(2, 'DOWN').toString();
  }
}

import type { LiquidateClaimUseCase } from '../application/LiquidateClaimUseCase.ts';
import { Settlement } from '../domain/model/Settlement.ts';
import type { ClaimInputMapper } from './ClaimInputMapper.ts';
import type { SettlementOutputMapper } from './SettlementOutputMapper.ts';

/** Adaptador de entrada: traduce Record<string,string> al caso de uso y de vuelta. */
export class LiquidationController {
  private readonly inputMapper: ClaimInputMapper;
  private readonly useCase: LiquidateClaimUseCase;
  private readonly outputMapper: SettlementOutputMapper;

  constructor(
    inputMapper: ClaimInputMapper,
    useCase: LiquidateClaimUseCase,
    outputMapper: SettlementOutputMapper,
  ) {
    this.inputMapper = inputMapper;
    this.useCase = useCase;
    this.outputMapper = outputMapper;
  }

  handle(input: Record<string, string>): Record<string, string> {
    const mapped = this.inputMapper.map(input);
    if (!mapped.ok) {
      return this.outputMapper.toRecord(Settlement.failed('ENTRADA_INVALIDA:' + mapped.field));
    }
    return this.outputMapper.toRecord(this.useCase.execute(mapped.command));
  }
}

import { LiquidateClaimUseCase } from './application/LiquidateClaimUseCase.ts';
import { ClaimLiquidationService } from './domain/services/ClaimLiquidationService.ts';
import { LiquidationPreconditions } from './domain/services/LiquidationPreconditions.ts';
