import { LiquidationController } from './infrastructure/LiquidationController.ts';
import { SettlementOutputMapper } from './infrastructure/SettlementOutputMapper.ts';

/** Composition root: compone dependencias y delega al caso de uso. */
export function execute(input: Record<string, string>): Record<string, string> {
  const useCase = new LiquidateClaimUseCase(
    new LiquidationPreconditions(),
    ClaimLiquidationService.standard(),
    new InMemoryAuditLog(),
  );
  const controller = new LiquidationController(
    new ClaimInputMapper(),
    useCase,
    new SettlementOutputMapper(),
  );
  return controller.handle(input);
}

import test from 'node:test';
